/**
 * Curated destination data generated by `npm run data:attractions` (scripts/build-attractions.mjs)
 * from Wikipedia and Wikimedia Commons. Photos are self-hosted under public/images/attractions.
 *
 * destinations.json is small (hero, one cover photo per country, featured order) and ships with
 * the app. attractions.json holds descriptions for every attraction, so it is split into its own
 * chunk and only loaded when a page needs it.
 */
import destinations from '../data/destinations.json';
import curated from '../data/curated-countries.json';

let attractionsRequest = null;

// Snapshot lookups: curated countries in the detail shape, and every country a curated one
// borders (code, name, flag) for the neighbour list.
const curatedByCode = new Map(curated.countries.map((country) => [country.code, country]));
const flagByCode = new Map(
  [...curated.countries, ...(curated.neighbours ?? [])].map((country) => [country.code, country]),
);

/** { hero, featured: [code], covers: { [code]: { name, src, large, width, height, credit } } } */
export function getDestinations() {
  return destinations;
}

/**
 * Country details (getCountry shape, so also usable as getAllCountries summaries) for the curated
 * destinations, snapshotted by `npm run data:countries`, so Explore can list them without calling
 * REST Countries.
 */
export function getCuratedCountries() {
  return curated.countries;
}

/** A curated country's details from the snapshot (instant, no request), or null. */
export function getCuratedCountry(code) {
  const country = curatedByCode.get(code?.toUpperCase());
  return country && Array.isArray(country.borders) ? country : null;
}

/**
 * Neighbour entries ({ code, name, flagUrl, flagAlt }) from the snapshot, in the given order, or
 * null if any code isn't in it (then the caller asks REST Countries).
 */
export function getSnapshotNeighbours(codes) {
  const found = codes.map((code) => flagByCode.get(code));
  return found.every(Boolean) ? found : null;
}

/** Cover photo for a country, or null when none is curated. */
export function getCoverPhoto(code) {
  return destinations.covers[code?.toUpperCase()] ?? null;
}

async function loadAttractionsData() {
  attractionsRequest ??= import('../data/attractions.json').then(
    (module) => module.default,
    (error) => {
      attractionsRequest = null; // let a retry load the chunk again
      throw error;
    },
  );
  return attractionsRequest;
}

/** Curated attractions for a country ([] when none). Rejects only if the data chunk can't load. */
export async function getAttractions(code) {
  const data = await loadAttractionsData();
  return data.countries[code.toUpperCase()] ?? [];
}

/** Every curated country's attractions: { [code]: attraction[] } (for the credits page). */
export async function getAllAttractions() {
  const data = await loadAttractionsData();
  return data.countries;
}
